### 3.2 Centralise secret loading (new file: `config/secrets.js`)

```js
// config/secrets.js
/**
 * Load configuration values from the environment.
 * In development we also load a .env file (ignored by Git).
 * In production you should supply these vars via your runtime
 * (Docker env, Kubernetes Secrets, or a managed secrets manager).
 */

const path = require('path');

// Load .env only when NODE_ENV !== 'production'.
// This ensures the file never gets read on a live server.
if (process.env.NODE_ENV !== 'production') {
  // `dotenv` will silently ignore a missing .env file.
  require('dotenv').config({ path: path.resolve(__dirname, '..', '.env') });
}

// Helper to require a variable and abort early if missing.
function required(name) {
  const val = process.env[name];
  if (!val) {
    console.error(`❌ Missing required environment variable: ${name}`);
    process.exit(1);
  }
  return val;
}

// Export the secrets your app actually needs.
module.exports = {
  // Example – database connection string
  DATABASE_URL: required('DATABASE_URL'),

  // Example – third‑party API keys
  ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,   // optional
  STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY, // optional

  // Add any other required secrets here.
};
```

### 3.3 Use the secrets in `app.js`

```js
// app.js
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const cors = require('cors');
const { DATABASE_URL } = require('./config/secrets'); // <-- pulls from env

const app = express();

app.disable('x-powered-by');
app.use(helmet());
app.use(cors({ origin: ['https://example.com'] }));
app.use(morgan('combined'));
app.use(rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
}));
app.use(express.json());

// Example: just log the DB URL (do NOT log it in production!)
if (process.env.NODE_ENV !== 'production') {
  console.log('🔑 Loaded DATABASE_URL:', DATABASE_URL);
}

// …rest of routes unchanged…

module.exports = app;
```

### 3.4 Production deployment (AWS example)

```bash
# 1️⃣ Store secret in AWS Secrets Manager
aws secretsmanager create-secret \
  --name my-app/DATABASE_URL \
  --secret-string "postgres://admin:real‑password@db.internal:5432/production"

# 2️⃣ Grant the task role permission to read the secret
# (e.g., attach a policy with `secretsmanager:GetSecretValue`)

# 3️⃣ In the container / ECS task definition, inject the secret as an env var:
#    {
#      "name": "DATABASE_URL",
#      "valueFrom": "arn:aws:ssm:us-east-1:123456789012:parameter/my-app/DATABASE_URL"
#    }

# 4️⃣ The Node process will see DATABASE_URL in process.env and the
#    `config/secrets.js` module will validate its presence at start‑up.
```

**Other cloud providers** have analogous flows (GCP Secret Manager → `GOOGLE_APPLICATION_CREDENTIALS`, Azure Key Vault → `AZURE_KEYVAULT_URL`). The pattern stays the same: **pull secrets at runtime from the platform, never check them into source control**.

### 3.5 CI / local development

* Add `.env` (or `.env.local`) to **`.gitignore`** – never commit it.  
  ```gitignore
  # .gitignore
  .env*
  ```
* Keep a **template** file (`.env.example`) that documents required keys without values:
  ```dotenv
  # .env.example
  DATABASE_URL=postgres://user:password@host:port/dbname
  ANTHROPIC_API_KEY=sk-...
  STRIPE_SECRET_KEY=sk_live_...
  ```

### 3.6 Detect accidental secret commits (defense‑in‑depth)

1. **Git secrets pre‑commit hook** – e.g., `git-secrets` or `detect-secrets`.
2. **CI scan** – `npm audit` + a secret‑scanner step (`trufflehog`, `gitleaks`).
3. **Rotate** any canary credentials you used for testing (the ones already in `.env.test`).

