// 1️⃣  Load modules
const express = require('express');
const helmet = require('helmet');           // Sets security‑related HTTP headers
const rateLimit = require('express-rate-limit'); // Simple DoS protection
const cors = require('cors');               // Define allowed origins
const morgan = require('morgan');           // Request logging
const jwt = require('jsonwebtoken');        // Example auth (replace with your strategy)
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// ----------------------------------------------------
// 2️⃣  Global Middleware
app.use(helmet());               // A6 – set many security headers automatically
