    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Encode any user‑generated fields before sending (prevent XSS)
  const safeUsers = users.map(u => ({
    id: u.id,
    name: require('escape-html')(u.name),   // npm i escape-html
    email: require('escape-html')(u.email),
  }));

  res.json(safeUsers);
});

/**
 * Example of a POST endpoint with validation & sanitisation
 * (illustrates how you would safely handle user supplied data)
 */
app.post(
  '/users',
  authenticate,
  validate([
    body('name').trim().isLength({ min: 1 }).escape(),
    body('email').isEmail().normalizeEmail(),
  ]),
  (req, res) => {
    // Assume you have a DB call here, using prepared statements / ORM.
    const { name, email } = req.body;
    // ... insert into DB ...
    res.status(201).json({ message: 'User created', user: { name, email } });
