3. **Exposes secrets via a clean, typed object** so the rest of the code can use `config.dbUrl`, `config.awsKeyId`, etc.  
4. **Fails fast** if required secrets are missing.

```js
// config.js ---------------------------------------------------------------
/* 1️⃣ Load .env only when NODE_ENV !== 'production' */
if (process.env.NODE_ENV !== 'production') {
  // `dotenv` is a tiny, zero‑runtime‑overhead dependency
  // npm i dotenv   <-- run this once
  require('dotenv').config({ path: `.env.${process.env.NODE_ENV}` });
}

/* 2️⃣ Helper to read a secret from the environment, throwing if missing */
function requiredEnv(name) {
  const val = process.env[name];
  if (!val) {
    throw new Error(`Missing required environment variable ${name}`);
  }
  return val;
}

/* 3️⃣ OPTIONAL: Pull secrets from AWS Secrets Manager if they aren't in env */
async function fetchAwsSecret(secretName) {
  const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
  const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });
  const command = new GetSecretValueCommand({ SecretId: secretName });
  const resp = await client.send(command);
  // Secrets may be stored as a JSON string; parse if needed
  return resp.SecretString ? JSON.parse(resp.SecretString) : {};
}

/* 4️⃣ Assemble the config object – sync part first */
const config = {
  // Basic required values
  port: Number(process.env.PORT) || 3000,
  apiToken: requiredEnv('API_TOKEN'),        // <-- your auth token
  dbUrl: process.env.DATABASE_URL,           // optional – may be fetched later
  awsAccessKeyId: process.env.AWS_ACCESS_KEY_ID,
  awsSecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
  anthropicApiKey: process.env.ANTHROPIC_API_KEY,
  stripeSecretKey: process.env.STRIPE_SECRET_KEY,
  logfireToken: process.env.LOGFIRE_TOKEN,
};

/* 5️⃣ If any of the above are undefined in prod, try the secret manager */
if (process.env.NODE_ENV === 'production') {
  (async () => {
    try {
      const secrets = await fetchAwsSecret('my-app-prod-secrets'); // replace with your secret name
      // Merge any missing values from the secret payload
      Object.assign(config, {
        dbUrl: config.dbUrl || secrets.DATABASE_URL,
        awsAccessKeyId: config.awsAccessKeyId || secrets.AWS_ACCESS_KEY_ID,
        awsSecretAccessKey: config.awsSecretAccessKey || secrets.AWS_SECRET_ACCESS_KEY,
        anthropicApiKey: config.anthropicApiKey || secrets.ANTHROPIC_API_KEY,
        stripeSecretKey: config.stripeSecretKey || secrets.STRIPE_SECRET_KEY,
        logfireToken: config.logfireToken || secrets.LOGFIRE_TOKEN,
      });

      // Final sanity check – abort if anything still missing
      ['apiToken', 'dbUrl'].forEach(k => {
        if (!config[k]) throw new Error(`Secret ${k} still missing after Secrets Manager fetch`);
      });
    } catch (e) {
      console.error('❌ Critical secret‑initialisation failure:', e);
      process.exit(1);   // Stop the process – better than running un‑secured
    }
  })();
}

/* 6️⃣ Export the ready‑to‑use config */
module.exports = config;
```

