  '/login',
  // Input validation (avoid injection, ensure correct shape)
  body('username').isString().trim().isLength({ min: 3, max: 30 }),
  body('password').isString().isLength({ min: 8 }), // realistic min‑length
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty())
      return res.status(400).json({ errors: errors.array() });

    const { username, password } = req.body;

    // ---- Dummy auth check (replace with real DB/BCrypt) ----
    if (username === 'admin' && password === 'SuperSecret123') {
      const payload = { sub: username, role: 'admin' };
      const token = jwt.sign(payload, process.env.JWT_SECRET, {
        expiresIn: '1h',
      });
      return res.json({ token });
    }

    return res.status(401).json({ error: 'Invalid credentials' });
  }
);

// ---------- Global Error Handler ----------
app.use((err, req, res, next) => {
  console.error(err); // <-- still logs to console (or Winston/Logstash)
  res.status(500).json({ error: 'Internal Server Error' });
});

// ---------- Server Startup ----------
