### 3.3 Harden the Express app

```js
// app.js
require('dotenv').config();          // Load .env early
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { port, trustProxy } = require('./config');

const app = express();

// --------------------
// 1. Core security middleware
// --------------------
app.use(helmet());                     // Sets security‑related HTTP headers
app.use(cors({                         // Adjust origins as needed
  origin: ['https://your‑frontend.com'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
}));
// Hide Express implementation details
app.disable('x-powered-by');

// --------------------
// 2. Rate limiting (basic DoS protection)
// --------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                 // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// --------------------
// 3. Body parsing & validation utilities
// --------------------
app.use(express.json()); // for future POST/PUT bodies

// --------------------
// 4. Logging (request + error)
// --------------------
app.use(morgan('combined')); // logs to stdout; pipe to a log aggregator

// --------------------
// 5. Trust proxy (important for correct client‑IP when behind load balancer)
// --------------------
if (trustProxy) app.set('trust proxy', 1);

// --------------------
// 6. Routes (keep them isolated in separate files for larger apps)
// --------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // In a real app, pull from DB with proper ACL checks
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
  // Example of a simple access‑control check:
  // if (!req.user || !req.user.isAdmin) return res.sendStatus(403);
  res.json(users);
});

// --------------------
// 7. Global error handler (avoid leaking stack traces)
// --------------------
app.use((err, req, res, next) => {
  console.error(err);          // Could be replaced by winston logger
  const status = err.status || 500;
  const message = status === 500 ? 'Internal Server Error' : err.message;
  res.status(status).json({ error: message });
});

// --------------------
// 8. HTTPS enforcement (when behind a reverse proxy)
// --------------------
app.use((req, res, next) => {
  if (req.secure || req.headers['x-forwarded-proto'] === 'https') {
    return next();
  }
  // Redirect HTTP → HTTPS
  res.redirect(`https://${req.headers.host}${req.originalUrl}`);
});

// --------------------
// 9. Start server
// --------------------
app.listen(port, () => {
  console.log(`Server running on port ${port}`);
});

module.exports = app;
```

### 3.4 Input Validation (future POST/PUT routes)

If you ever add a route that accepts user‑supplied data, **always validate** it with a schema library such as **Joi**:

```js
const Joi = require('joi');

// Example: create a new user
app.post('/users', (req, res, next) => {
  const schema = Joi.object({
    name: Joi.string().min(2).max(100).required(),
    email: Joi.string().email().required(),
    password: Joi.string().min(8).required(),
  });

  const { error, value } = schema.validate(req.body);
  if (error) {
    // 400 Bad Request – malformed input
    return res.status(400).json({ error: error.details[0].message });
  }

  // Proceed with sanitized `value`
  // e.g., hash password with bcrypt, store in DB, etc.
  res.status(201).json({ id: 123, ...value });
});
```

### 3.5 Authentication & Authorization (recommended starter)

Add **JSON Web Token (JWT)** based auth for protected routes, or plug in a session store.

```bash
npm install jsonwebtoken bcryptjs
```

```js
const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');
const secret = process.env.JWT_SECRET; // set in .env, >256‑bit random string

// Middleware to protect routes
function authenticate(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader) return res.sendStatus(401); // No token

  const token = authHeader.split(' ')[1];
  try {
    const payload = jwt.verify(token, secret);
    req.user = payload; // Attach user info to request
    next();
  } catch (e) {
    return res.sendStatus(403); // Invalid token
  }
}

// Example protected endpoint
app.get('/admin/users', authenticate, (req, res) => {
  if (!req.user.isAdmin) return res.sendStatus(403);
  // Return privileged data…
});
```

> **Tip:** Rotate `JWT_SECRET` regularly and store it in a secrets manager (AWS Secrets Manager, HashiCorp Vault, etc.).

