## Sample Refactored `app.js` (including the secret‑loader)

Below is a **complete, ready‑to‑run** version that ties all the recommendations together. Feel free to replace the AWS‑specific parts with your own secret‑manager SDK if you’re on another cloud.

```js
// ----------------------------------------------------------
// Secure Express Application (with managed secrets)
// ----------------------------------------------------------

require('dotenv-safe').config({            // guarantees required vars exist
  example: '.env.example',
  path: '.env',                           // optional local dev file
});

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');
const { getSecret } = require('./secrets'); // <-- wrapper for secret manager
const logger = require('pino')({ level: process.env.LOG_LEVEL || 'info' });

const app = express();

// ----------------------------------------------------------
// Load production secrets (run *before* any request handling)
// ----------------------------------------------------------
(async () => {
  try {
    const secretId = process.env.SECRETS_ID; // set via k8s / docker env
    if (!secretId) throw new Error('SECRETS_ID env var missing');

    const secretConfig = await getSecret(secretId);
    // Inject only what we need; keep secrets in memory, NOT in process.env
    process.env.JWT_SECRET = secretConfig.JWT_SECRET;
    process.env.DATABASE_URL = secretConfig.DATABASE_URL;
    // add any other needed keys ...

    logger.info({ msg: 'Secrets loaded', keys: Object.keys(secretConfig) });
  } catch (e) {
    logger.error({ err: e }, '❗ Failed to load secrets – aborting start');
    process.exit(1);
  }
})();

// ----------------------------------------------------------
// Global security middle‑wares (run after the secret loader)
// ----------------------------------------------------------
app.disable('x-powered-by');
app.use(helmet());
app.use(
  cors({
    origin: process.env.ALLOWED_ORIGINS?.split(',') || '*',
  })
);
app.use(morgan('combined'));
app.use(express.json({ limit: '10kb' }));

// Rate limiting
app.use(
  rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 100,
    standardHeaders: true,
    legacyHeaders: false,
  })
);

// ----------------------------------------------------------
// Auth helpers (JWT)
// ----------------------------------------------------------
function generateToken(payload) {
  return jwt.sign(payload, process.env.JWT_SECRET, { expiresIn: '1h' });
}
function verifyToken(token) {
  try {
    return jwt.verify(token, process.env.JWT_SECRET);
  } catch {
    return null;
  }
}
function requireAuth(req, res, next) {
  const auth = req.headers.authorization;
  if (!auth?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing Bearer token' });
  }
  const payload = verifyToken(auth.split(' ')[1]);
  if (!payload) return res.status(401).json({ error: 'Invalid token' });
  req.user = payload;
  next();
}

// ----------------------------------------------------------
// Example data (in‑memory) – keep PII out of public routes
// ----------------------------------------------------------
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

// ----------------------------------------------------------
// Routes
// ----------------------------------------------------------
app.get('/health', (req, res) =>
  res.json({ status: 'ok', timestamp: new Date().toISOString() })
);

app.post('/login', (req, res) => {
  const { username } = req.body;
  if (!username) return res.status(400).json({ error: 'username required' });
  // In real world: validate password, look up user, etc.
  const token = generateToken({ sub: username, canViewEmail: true });
  res.json({ token });
});

app.get('/users', requireAuth, (req, res) => {
  const safe = users.map(u => ({
    id: u.id,
    name: u.name,
    email: req.user.canViewEmail ? u.email : undefined,
  }));
  res.json(safe);
});

// ----------------------------------------------------------
// Global error handler
// ----------------------------------------------------------
app.use((err, _req, res, _next) => {
  logger.error({ err }, 'Unhandled error');
  const status = err.status || 500;
  const msg = status === 500 ? 'Internal Server Error' : err.message;
  res.status(status).json({ error: msg });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => logger.info(`🚀 Server listening on ${PORT}`));

module.exports = app;
```

**Note** – the secret‑loading IIFE executes *once* at start‑up. If your deployment expects hot‑reloading of secrets (e.g., rotation without restart), you can replace the IIFE with a small background poller that refreshes the in‑memory configuration and updates required components (JWT secret, DB pool, etc.).

