### A01 – Broken Access Control  
**Issue:** `/users` is publicly accessible; there is no authentication or role checking.  

**Fix:** Add a JWT‑based authentication middleware (or any other strategy) and protect sensitive routes.

```js
// auth.js – a minimal JWT guard
const jwt = require('jsonwebtoken');

const authGuard = (req, res, next) => {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing token' });
  }

  const token = authHeader.split(' ')[1];
  try {
    // Replace 'your‑jwt‑secret' with a secret stored in .env
    const payload = jwt.verify(token, process.env.JWT_SECRET);
    req.user = payload;               // attach user info for later RBAC checks
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid token' });
  }
};

module.exports = authGuard;
```

