```js
// ----------- src/secrets.js ------------------------------------
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });

/**
 * Fetches a secret JSON string from AWS Secrets Manager and merges it
 * into process.env.  If a secret is missing, the function logs a warning
 * but does not crash the process (so the app can still start in dev).
 */
async function loadAwsSecrets(secretId) {
  try {
    const command = new GetSecretValueCommand({ SecretId: secretId });
    const { SecretString } = await client.send(command);
    const secretObj = JSON.parse(SecretString);

    // Populate process.env (only if not already defined)
    Object.entries(secretObj).forEach(([key, value]) => {
      if (!process.env[key]) {
        process.env[key] = value;
      }
    });

    console.log(`✔ Secrets loaded from ${secretId}`);
  } catch (err) {
    console.error(`⚠️ Could not load secrets from ${secretId}:`, err);
  }
}

module.exports = { loadAwsSecrets };
```

