```javascript
// config.js
// Centralised configuration & secret loading

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const dotenv = require('dotenv');

// -------------------------------------------------------------------
// 1️⃣ Load .env only when NOT running in production (helps local dev)
// -------------------------------------------------------------------
if (process.env.NODE_ENV !== 'production') {
  const result = dotenv.config(); // loads .env into process.env
  if (result.error) {
    console.warn('⚠️  No .env file found – relying on existing environment variables');
  }
}

// -------------------------------------------------------------------
// 2️⃣ Helper to fetch a secret from AWS Secrets Manager (or any manager)
// -------------------------------------------------------------------
async function getSecret(secretName) {
  const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });
  const command = new GetSecretValueCommand({ SecretId: secretName });
  const response = await client.send(command);

  // Secrets can be stored as plain text or JSON string
  if (response.SecretString) {
    try {
      return JSON.parse(response.SecretString);
    } catch {
      // Not JSON – return raw string
      return response.SecretString;
    }
  }
  throw new Error(`Secret ${secretName} has no string value`);
}

// -------------------------------------------------------------------
// 3️⃣ Load required config values
// -------------------------------------------------------------------
async function loadConfig() {
  // Required runtime environment variables
  const requiredEnv = ['PORT', 'AWS_REGION', 'JWT_SECRET_NAME', 'CORS_ORIGIN'];
  requiredEnv.forEach(key => {
    if (!process.env[key]) {
      throw new Error(`❌ Missing required environment variable: ${key}`);
    }
  });

  // Pull the JWT secret (and any other secrets) from the secrets manager
  const jwtSecretPayload = await getSecret(process.env.JWT_SECRET_NAME);
  // Assume the secret stored is either a raw string or { "value": "actual-secret" }
  const JWT_SECRET = typeof jwtSecretPayload === 'string'
    ? jwtSecretPayload
    : jwtSecretPayload.value;

  if (!JWT_SECRET) {
    throw new Error('❌ JWT secret retrieved but empty');
  }

  return {
    PORT: parseInt(process.env.PORT, 10),
    JWT_SECRET,
    CORS_ORIGIN: process.env.CORS_ORIGIN,
    // Add any other config values you need, e.g., DB connection strings, API keys…
  };
}

// Export a promise – the caller must `await loadConfig()` before starting the server
module.exports = { loadConfig };
```

### 3️⃣ Wire the config loader into `app.js`

```javascript
// app.js (trimmed for clarity)
// -----------------------------------------------------------
// 1️⃣ Load configuration at startup (fails fast if missing)
// -----------------------------------------------------------
const { loadConfig } = require('./config');

(async () => {
  try {
    const { PORT, JWT_SECRET, CORS_ORIGIN } = await loadConfig();

    // -----------------------------------------------------------------
    // 2️⃣ The rest of the app – unchanged except that we use the loaded values
    // -----------------------------------------------------------------
    const express = require('express');
    const helmet = require('helmet');
    const cors = require('cors');
    const rateLimit = require('express-rate-limit');
    const morgan = require('morgan');
    const jwt = require('jsonwebtoken');
    const { param, body, query, validationResult } = require('express-validator');

    const app = express();

    app.use(helmet());
    app.disable('x-powered-by');
    app.use(cors({ origin: CORS_ORIGIN, credentials: true }));
    app.use(express.json());
    app.use(morgan('combined'));
    app.use(rateLimit({ windowMs: 60_000, max: 100 }));

    // Auth middleware now uses the real secret (no default fallback)
    function authenticateToken(req, res, next) {
      const authHeader = req.headers.authorization;
      const token = authHeader && authHeader.split(' ')[1];
      if (!token) return res.status(401).json({ error: 'Missing token' });

      jwt.verify(token, JWT_SECRET, (err, user) => {
        if (err) return res.status(403).json({ error: 'Invalid token' });
        req.user = user;
        next();
      });
    }

    // ...existing routes (health, users)...
    app.get('/health', (req, res) => {
      res.json({ status: 'ok', timestamp: new Date().toISOString() });
    });

