  param('id').isInt({ gt: 0 }).toInt(),
  validate,
], (req, res) => {
  // safe to use req.params.id as a number now
});
```

*Why*: Prevents injection attacks (SQL/NoSQL) and ensures type safety.

### 2.6. Authentication & Authorization Skeleton

Start with JWT‑based auth (or any strategy that fits your needs). You can protect the `/users` endpoint right away.

```js
const jwt = require('jsonwebtoken');

// Middleware to verify JWT
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer <token>

  if (!token) return res.sendStatus(401); // Unauthorized

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.sendStatus(403); // Invalid token
    req.user = user; // attach decoded payload
    next();
  });
}

// Protect the /users route
app.get('/users', authenticateToken, (req, res) => {
  // you could filter users based on req.user.role etc.
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

*Why*: Without authentication, any client can retrieve user data. Adding JWT (or session‑based) auth establishes a baseline.

### 2.7. Centralised Error Handling

```js
// 1️⃣  Catch async errors (if you start using async handlers)
require('express-async-errors'); // add to dependencies

// 2️⃣  Global error handler (must be AFTER all routes)
app.use((err, req, res, next) => {
  console.error(err); // could be replaced with a proper logger (winston/pino)
