    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;
```

The app only serves two `GET` routes:

| Route | Purpose | Current behaviour |
|-------|---------|-------------------|
| `/health` | Liveness/health check | Returns static JSON with a timestamp |
| `/users`  | Returns a hard‑coded list of user records (including email) | No authentication, no rate‑limiting, no security headers |

Even though the code is tiny, it already exhibits several **OWASP Top 10** concerns:

| OWASP Category | Issue in the current code | Why it matters |
|----------------|---------------------------|----------------|
| A01 ‑ Broken Access Control | `/users` is publicly accessible and discloses personal data (email addresses). | Anyone (including bots) can enumerate real‑world‑like user data. |
| A02 ‑ Cryptographic Failures | No TLS/HTTPS enforcement at the application level. | Data could be intercepted in transit (especially in non‑local deployments). |
| A04 ‑ Insecure Design | Lack of authentication/authorization framework. | No way to restrict who can call the API. |
| A05 ‑ Security Misconfiguration | `X‑Powered‑By: Express` header is left enabled; no Helmet or other hardening. | Gives attackers information about the stack. |
| A06 ‑ Vulnerable & Out‑dated Components | No version pinning / dependency checking shown (but worth reviewing in `package.json`). |
| A07 ‑ Cross‑Site Scripting (XSS) | Not present now, but future endpoints that render data could be vulnerable if input isn’t validated/escaped. |
| A08 ‑ Insecure Deserialization | No deserialization in current code, but a future `POST` body parser without validation could be risky. |
| A09 ‑ Identification & Authentication Failures | No authentication at all. |
| A10 ‑ Logging & Monitoring | No request logging, error handling, or audit trails. |

