## 3. Consolidated Revised `app.js`

Below is a **complete, ready‑to‑run** version that incorporates all the above hardening steps while preserving the original functionality.

```js
// app.js – Hardened version
require('dotenv-safe').config(); // loads .env and validates required vars

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const pino = require('pino');
const pinoHttp = require('pino-http');

const app = express();
const logger = pino({ level: process.env.LOG_LEVEL || 'info' });

/* -------------------- Global Middleware -------------------- */
app.set('trust proxy', 1);               // needed when behind a reverse proxy
app.use(helmet());                       // secure HTTP headers
app.disable('x-powered-by');             // hide Express info
app.use(pinoHttp({ logger }));           // structured request logging
app.use(express.json());                 // JSON body parsing for POST/PUT

/* -------------------- Rate Limiting -------------------- */
const globalLimiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(globalLimiter);

/* -------------------- Auth Helpers -------------------- */
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];
  if (!token) return res.sendStatus(401);

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.sendStatus(403);
    req.user = user;
    next();
  });
}

/* -------------------- Routes -------------------- */

// Health check – freely accessible
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Example login – issues a JWT (replace with real credential checks!)
app.post('/login', rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: 'Too many login attempts, please try again later.',
}), (req, res) => {
  const { username } = req.body;
  // TODO: validate username/password against a real data store
  const user = { name: username, role: username === 'admin' ? 'admin' : 'user' };
  const token = jwt.sign(user, process.env.JWT_SECRET, { expiresIn: '1h' });
  res.json({ accessToken: token });
});

// Protected users endpoint – only authenticated callers
app.get('/users', authenticateToken, (req, res) => {
  const isAdmin = req.user.role === 'admin';
  const users = [
    { id: 1, name: 'Alice', email: isAdmin ? 'alice@example.com' : undefined },
    { id: 2, name: 'Bob',   email: isAdmin ? 'bob@example.com'   : undefined },
  ];
  res.json(users);
});

/* -------------------- Error Handling -------------------- */
app.use((err, req, res, next) => {
  // Log the full error for ops, but never expose stack traces to clients
  logger.error(err);
  const status = err.status || 500;
  const safeMessage = status === 500 ? 'Internal server error' : err.message;
  res.status(status).json({ message: safeMessage });
});

/* -------------------- Server Startup -------------------- */
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

module.exports = app;
```

**How to run the hardened version:**

```bash
