## 2. Refactor Secret Loading

### 2.1. Install AWS SDK (v3)

```bash
npm install @aws-sdk/client-secrets-manager @aws-sdk/credential-provider-node
```

### 2.2. Create a tiny **SecretProvider** module

Create a new file **`config/secretProvider.js`**:

```js
// config/secretProvider.js
const { SecretsManagerClient, GetSecretValueCommand } = require("@aws-sdk/client-secrets-manager");
const { fromEnv, fromIni, fromInstanceMetadata, fromNodeProviderChain } = require("@aws-sdk/credential-provider-node");

/**
 * Returns the value of a secret.
 *
 * @param {string} secretId   - The full ARN or name of the secret in AWS Secrets Manager.
 * @param {Object} [options] - Optional overrides.
 * @returns {Promise<string>} The secret string (or JSON string that you can JSON.parse).
 */
async function getSecret(secretId, options = {}) {
  // Build a client that automatically picks up credentials from the environment,
  // shared credentials file, EC2/ECS metadata, etc.
  const client = new SecretsManagerClient({
    region: process.env.AWS_REGION || "us-east-1",
    credentials: fromNodeProviderChain(),
    ...options.clientConfig,
  });

  const command = new GetSecretValueCommand({ SecretId: secretId });

  const response = await client.send(command);
  if (response.SecretString) {
    return response.SecretString;
  }
  // If the secret is stored as binary (unlikely for JWT secret) we decode it.
  if (response.SecretBinary) {
    return Buffer.from(response.SecretBinary, "base64").toString("utf-8");
  }
  throw new Error(`Secret ${secretId} has no retrievable value`);
}

/**
 * Helper that returns a parsed JSON secret (if you store a JSON object).
 * @param {string} secretId
 * @returns {Promise<Object>}
 */
async function getSecretJson(secretId) {
  const raw = await getSecret(secretId);
  try {
    return JSON.parse(raw);
  } catch (_) {
    // If it is not JSON, just return the raw string
    return raw;
  }
}

module.exports = { getSecret, getSecretJson };
```

### 2.3. Load the JWT secret at startup (with a fallback for local dev)

Edit **`app.js`** near the top (replace the existing `require('dotenv-safe').config();` line):

```js
// app.js – revised secret loading
const { getSecret } = require("./config/secretProvider");

// ---------------------------------------------------
// Helper: fetch JWT secret (cloud or local fallback)
// ---------------------------------------------------
async function loadJwtSecret() {
  // In production we expect the secret to live in AWS Secrets Manager.
  // The name/ARN is supplied via an env var so that the code stays
  // environment‑agnostic (same code works on dev, staging, prod).
  const secretId = process.env.JWT_SECRET_ARN; // e.g. "arn:aws:secretsmanager:us-east-1:123456789012:secret:myJwtSecret-abc123"

  if (!secretId) {
    // No ARN? Fall back to local .env (development only)
    require('dotenv-safe').config(); // pulls JWT_SECRET from .env
    if (!process.env.JWT_SECRET) {
      throw new Error("JWT_SECRET not defined – set JWT_SECRET (dev) or JWT_SECRET_ARN (prod)");
    }
    return process.env.JWT_SECRET;
  }

  // When running in AWS, the SDK will automatically use the role attached to the instance/task.
  const secretValue = await getSecret(secretId);
  return secretValue; // string containing the secret
}

// ---------------------------------------------------
// Async IIFE to bootstrap the server with the secret
// ---------------------------------------------------
(async () => {
  const jwtSecret = await loadJwtSecret();

  // ---- rest of the original app setup (express, middlewares, routes) ----
  const express = require('express');
  const helmet = require('helmet');
  const rateLimit = require('express-rate-limit');
  const pino = require('pino');
  const pinoHttp = require('pino-http');
  const jwt = require('jsonwebtoken');

  const app = express();
  const logger = pino({ level: process.env.LOG_LEVEL || 'info' });

  /* Global middleware (same as before) */
  app.set('trust proxy', 1);
  app.use(helmet());
  app.disable('x-powered-by');
  app.use(pinoHttp({ logger }));
  app.use(express.json());

  const globalLimiter = rateLimit({ windowMs: 60_000, max: 100 });
  app.use(globalLimiter);

  // -----------------------------------------
  // Authentication middleware (now uses the loaded secret)
  // -----------------------------------------
  function authenticateToken(req, res, next) {
    const authHeader = req.headers['authorization'];
    const token = authHeader && authHeader.split(' ')[1];
    if (!token) return res.sendStatus(401);
    jwt.verify(token, jwtSecret, (err, user) => {
      if (err) return res.sendStatus(403);
      req.user = user;
      next();
    });
  }

  // ----- routes (unchanged) -----
  app.get('/health', (req, res) => {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  });

  // ... login route, /users route, error handler, server listen, etc.
  // (copy the implementations from the hardened version shown earlier)

  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    logger.info(`Server running on port ${PORT}`);
  });

  // Export for testing
  module.exports = app;
})();
```

**What changed?**

* The secret is fetched **once, at startup**, from AWS Secrets Manager if an ARN (`JWT_SECRET_ARN`) is provided.
* For local development a `.env` file is still honoured, but **only because the ARN variable is missing** – this prevents accidental production use of a plain‑text secret.
* The secret is **not stored in the source tree**; it lives in a managed service that offers:
  * Encryption at rest (KMS‑managed keys).
  * Automatic rotation (you can configure rotation intervals).
  * Fine‑grained IAM policies (`secretsmanager:GetSecretValue` on the specific secret ARN).
  * Audit logging in CloudTrail.

