## Recommendations & Code Samples

Below are concrete steps you can take **right now** to harden the application, followed by examples for each.

### 1. Add Core Security Middleware

```js
// app.js (top)
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');           // basic XSS sanitisation
const mongoSanitize = require('express-mongo-sanitize'); // if you ever use MongoDB

// 1️⃣ Secure HTTP headers
app.use(helmet());

// 2️⃣ CORS – restrict to known origins (adjust the whitelist)
const whitelist = ['https://myapp.example.com'];
const corsOptions = {
  origin: function (origin, callback) {
    // allow non‑browser (e.g., health check) requests without origin
    if (!origin) return callback(null, true);
    if (whitelist.includes(origin)) {
      return callback(null, true);
    }
    callback(new Error('Not allowed by CORS'));
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  credentials: true,
};
app.use(cors(corsOptions));

// 3️⃣ Rate limiting – protects against brute force / DoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 4️⃣ Body parser (JSON) + sanitisation
app.use(express.json({ limit: '10kb' })); // limit payload size
app.use(xss());
app.use(mongoSanitize());

// 5️⃣ Basic error‑handler (do NOT leak stack traces in prod)
app.use((err, req, res, next) => {
  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal server error'
    : err.message;
  res.status(status).json({ error: message });
});
```

**Why?**  
- `helmet` sets 10+ security‑related HTTP headers (CSP, HSTS, X‑Frame‑Options, etc.).  
- `cors` prevents any website from calling your API unless you explicitly allow it.  
- `express-rate-limit` thwarts credential‑stuffing, scraping, and basic DoS.  
- `xss-clean` & `express-mongo-sanitize` give you a baseline against injection attacks when you later accept client data.  
- The generic error handler avoids leaking stack traces in production (A06).

### 2. Enforce HTTPS / HSTS

If you terminate TLS in a reverse proxy (NGINX, load balancer) you can still tell browsers to always use HTTPS:

```js
// after helmet()
app.use(
  helmet.hsts({
    maxAge: 31536000, // 1 year in seconds
    includeSubDomains: true,
    preload: true,
  })
);
```

If you run the Node server directly, you can make it listen only on HTTPS:

```js
// server.js (separate file for clarity)
const https = require('https');
const fs = require('fs');
const app = require('./app');

const sslOptions = {
  key: fs.readFileSync(process.env.SSL_KEY_PATH),
  cert: fs.readFileSync(process.env.SSL_CERT_PATH),
};

https.createServer(sslOptions, app).listen(process.env.PORT || 443, () => {
  console.log('HTTPS server listening');
});
```

> **Tip:** Store keys in a secure secret manager (AWS KMS, HashiCorp Vault, etc.) – never commit them to the repo.

### 3. Protect the `/users` Endpoint (Authentication & Authorization)

For a production API you’ll likely want JWT‑based auth. Below is a minimal example using `express-jwt` (or the newer `jwt` middleware from `express-oauth2-jwt-bearer`).

```js
// install: npm i jsonwebtoken express-jwt
const jwt = require('express-jwt');
const jwksRsa = require('jwks-rsa');

// 1️⃣ JWT verification middleware
const checkJwt = jwt({
  secret: jwksRsa.expressJwtSecret({
    cache: true,
    rateLimit: true,
    jwksUri: process.env.JWKS_URI, // e.g., Auth0 domain/.well-known/jwks.json
  }),
  audience: process.env.JWT_AUDIENCE,
  issuer: process.env.JWT_ISSUER,
  algorithms: ['RS256'],
});

// 2️⃣ Role‑based guard (simple example)
function requireAdmin(req, res, next) {
  // Assuming the JWT payload contains a `roles` array
  if (req.auth && req.auth.roles && req.auth.roles.includes('admin')) {
    return next();
  }
  return res.status(403).json({ error: 'Forbidden' });
}

// Secure the route
app.get('/users', checkJwt, requireAdmin, (req, res) => {
  // In a real app pull from DB, apply pagination, hide sensitive fields, etc.
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);
});
```

**Key points:**

- **Authentication** (`checkJwt`) ensures only callers presenting a valid token can reach the route.  
- **Authorization** (`requireAdmin`) demonstrates a simple role check; tailor it to your own business logic.  
- **Data minimisation**: Only return non‑sensitive fields (`email` removed). If you must expose email, consider a separate “profile” endpoint that respects the requesting user’s scope.

### 4. Input Validation (Future‑Proof)

When you add POST/PUT routes, adopt a schema‑validation library such as **Joi**, **zod**, or **express-validator**.

```js
// Example using Joi
