| **Never commit raw secrets** | Store them in a dedicated secrets‑management service (AWS Secrets Manager, Azure Key Vault, Google Secret Manager, HashiCorp Vault, etc.). | ```js // secrets.js <br> const { SecretsManagerClient, GetSecretValueCommand } = require("@aws-sdk/client-secrets-manager"); <br> const client = new SecretsManagerClient({ region: process.env.AWS_REGION }); <br> async function getSecret(name) { <br>   const cmd = new GetSecretValueCommand({ SecretId: name }); <br>   const { SecretString } = await client.send(cmd); <br>   return JSON.parse(SecretString); <br> } <br> module.exports = { getSecret }; ``` |
